<template><section class="module-page module-composed-page"><header class="module-heading"><div><h1>资源中心</h1><p>查看课程资源并发送到自己的实训环境，不支持下载到电脑。</p></div><el-button icon="el-icon-monitor" @click="$router.push('/training-environment')">选择实训环境</el-button></header><div class="course-filters"><el-input v-model="keyword" prefix-icon="el-icon-search" clearable placeholder="按资源名称搜索" /><el-select v-model="type" clearable placeholder="资源类型"><el-option v-for="item in types" :key="item" :label="item" :value="item" /></el-select></div><div class="module-table-wrap"><el-table v-loading="loading" :data="filtered" empty-text="暂无可用资源"><el-table-column prop="name" label="资源名称" min-width="220" /><el-table-column prop="resourceType" label="类型" width="110" /><el-table-column prop="courseName" label="所属课程" min-width="180" /><el-table-column label="下发状态" width="110"><template slot-scope="s"><el-tag size="small" :type="deliveryType(s.row.deliveryState)">{{ deliveryText(s.row.deliveryState) }}</el-tag></template></el-table-column><el-table-column label="操作" width="160" align="right"><template slot-scope="s"><el-button size="small" icon="el-icon-monitor" @click="$router.push({ path: '/training-environment', query: { courseId: s.row.courseId } })">发送到实训</el-button></template></el-table-column></el-table></div></section></template>
<script>
import { listUserCourses, listCourseDeliveries } from '@/api/Courses'
export default { data:()=>({loading:false,rows:[],deliveries:{},keyword:'',type:'',refreshTimer:null}), computed:{types(){return [...new Set(this.rows.map(r=>r.resourceType))]},filtered(){return this.rows.filter(r=>(!this.keyword||r.name.includes(this.keyword))&&(!this.type||r.resourceType===this.type))}}, async created(){await this.load();this.refreshTimer=setInterval(this.refreshDeliveries,10000)}, beforeDestroy(){clearInterval(this.refreshTimer)}, methods:{async load(){this.loading=true;try{const [courses,deliveries]=await Promise.all([listUserCourses(),listCourseDeliveries()]);this.deliveries={};(deliveries.data||[]).forEach(item=>{this.deliveries[item.resourceId]=item.state});this.rows=(courses.data||[]).reduce((all,item)=>all.concat((item.resources||[]).map(resource=>Object.assign({},resource,{courseName:item.course.name,courseId:item.course.courseId,deliveryState:this.deliveries[resource.resourceId]}))),[])}finally{this.loading=false}},async refreshDeliveries(){try{const result=await listCourseDeliveries();(result.data||[]).forEach(item=>{this.deliveries[item.resourceId]=item.state;const row=this.rows.find(resource=>resource.resourceId===item.resourceId);if(row)row.deliveryState=item.state})}catch(error){}},deliveryText(s){return({PENDING:'排队中',DISPATCHED:'已提交',RUNNING:'执行中',SUCCEEDED:'已完成',FAILED:'失败'})[s]||'未发送'},deliveryType(s){return s==='SUCCEEDED'?'success':s==='FAILED'?'danger':s?'warning':'info'}}}
</script>
